CREATE TABLE forms_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL, artifact_id TEXT NOT NULL, version TEXT NOT NULL, title TEXT);
CREATE TABLE forms_structure_child (id INTEGER PRIMARY KEY REFERENCES forms_document(id), child_id TEXT NOT NULL, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE forms_results_child (id INTEGER PRIMARY KEY REFERENCES forms_document(id), child_id TEXT NOT NULL, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE forms_step (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES forms_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), step_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT);
CREATE TABLE forms_question (id INTEGER PRIMARY KEY, step_id INTEGER NOT NULL REFERENCES forms_step(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), question_id TEXT NOT NULL, label TEXT NOT NULL, kind TEXT NOT NULL, description TEXT, required INTEGER CHECK(required IN (0,1)), placeholder TEXT, default_value_id INTEGER REFERENCES forms_value(id), minimum REAL, minimum_ieee754_bits INTEGER, minimum_numeric_class TEXT CHECK(minimum_numeric_class IN ('finite','positiveInfinity','negativeInfinity','nan')), maximum REAL, maximum_ieee754_bits INTEGER, maximum_numeric_class TEXT CHECK(maximum_numeric_class IN ('finite','positiveInfinity','negativeInfinity','nan')), increment REAL, increment_ieee754_bits INTEGER, increment_numeric_class TEXT CHECK(increment_numeric_class IN ('finite','positiveInfinity','negativeInfinity','nan')), unit TEXT, text TEXT, options_present INTEGER NOT NULL CHECK(options_present IN (0,1)), fields_present INTEGER NOT NULL CHECK(fields_present IN (0,1)), schema TEXT, src TEXT, accept TEXT, fixture_slug TEXT, params_value_id INTEGER REFERENCES forms_value(id), condition_id INTEGER REFERENCES forms_condition(id));
CREATE TABLE forms_option (id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL REFERENCES forms_question(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, label TEXT NOT NULL);
CREATE TABLE forms_vector_field (id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL REFERENCES forms_question(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), key TEXT NOT NULL, label TEXT, value REAL, value_ieee754_bits INTEGER, value_numeric_class TEXT CHECK(value_numeric_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE forms_response (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES forms_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), response_id TEXT NOT NULL, submitted_at_high INTEGER NOT NULL CHECK(submitted_at_high BETWEEN 0 AND 4294967295), submitted_at_low INTEGER NOT NULL CHECK(submitted_at_low BETWEEN 0 AND 4294967295), definition_version TEXT NOT NULL);
CREATE TABLE forms_answer (id INTEGER PRIMARY KEY, response_id INTEGER NOT NULL REFERENCES forms_response(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), question_id TEXT NOT NULL, label TEXT NOT NULL, kind TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES forms_value(id));
CREATE TABLE forms_condition (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('const','var','eq','and','or','truthy')));
CREATE TABLE forms_condition_const (id INTEGER PRIMARY KEY REFERENCES forms_condition(id), value_id INTEGER NOT NULL REFERENCES forms_value(id));
CREATE TABLE forms_condition_var (id INTEGER PRIMARY KEY REFERENCES forms_condition(id), name TEXT NOT NULL);
CREATE TABLE forms_condition_eq (id INTEGER PRIMARY KEY REFERENCES forms_condition(id), left_id INTEGER NOT NULL REFERENCES forms_condition(id), right_id INTEGER NOT NULL REFERENCES forms_condition(id));
CREATE TABLE forms_condition_and (id INTEGER PRIMARY KEY REFERENCES forms_condition(id));
CREATE TABLE forms_condition_or (id INTEGER PRIMARY KEY REFERENCES forms_condition(id));
CREATE TABLE forms_condition_truthy (id INTEGER PRIMARY KEY REFERENCES forms_condition(id), expression_id INTEGER NOT NULL REFERENCES forms_condition(id));
CREATE TABLE forms_condition_item (id INTEGER PRIMARY KEY, condition_id INTEGER NOT NULL REFERENCES forms_condition(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value_id INTEGER NOT NULL REFERENCES forms_condition(id));
CREATE TABLE forms_value (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('null','boolean','unsigned','signed','float','text','bytes','array','object')));
CREATE TABLE forms_null (id INTEGER PRIMARY KEY REFERENCES forms_value(id));
CREATE TABLE forms_boolean (id INTEGER PRIMARY KEY REFERENCES forms_value(id), value INTEGER NOT NULL CHECK(value IN (0,1)));
CREATE TABLE forms_unsigned (id INTEGER PRIMARY KEY REFERENCES forms_value(id), high INTEGER NOT NULL CHECK(high BETWEEN 0 AND 4294967295), low INTEGER NOT NULL CHECK(low BETWEEN 0 AND 4294967295));
CREATE TABLE forms_signed (id INTEGER PRIMARY KEY REFERENCES forms_value(id), value INTEGER NOT NULL);
CREATE TABLE forms_float (id INTEGER PRIMARY KEY REFERENCES forms_value(id), value REAL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL CHECK(value_numeric_class IN ('finite','positiveInfinity','negativeInfinity','nan')));
CREATE TABLE forms_text (id INTEGER PRIMARY KEY REFERENCES forms_value(id), value TEXT NOT NULL);
CREATE TABLE forms_bytes (id INTEGER PRIMARY KEY REFERENCES forms_value(id));
CREATE TABLE forms_octet (id INTEGER PRIMARY KEY, bytes_id INTEGER NOT NULL REFERENCES forms_bytes(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 255));
CREATE TABLE forms_array (id INTEGER PRIMARY KEY REFERENCES forms_value(id));
CREATE TABLE forms_array_element (id INTEGER PRIMARY KEY, array_id INTEGER NOT NULL REFERENCES forms_array(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value_id INTEGER NOT NULL REFERENCES forms_value(id));
CREATE TABLE forms_object (id INTEGER PRIMARY KEY REFERENCES forms_value(id));
CREATE TABLE forms_object_member (id INTEGER PRIMARY KEY, object_id INTEGER NOT NULL REFERENCES forms_object(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), name TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES forms_value(id));

